svg.script:
// Fits the name into the lower third: one line if possible, otherwise two lines (preferably between first and
// last name, else after a hyphen). A name that only slightly doesn't fit is scaled down a bit instead, and a
// name that still doesn't fit (e.g. one very long word) is scaled down until it does.
(function () {
  function layout() {
    var bar = document.querySelector('.lower-third .name');
    if (!bar) {
      return;
    }
    var maxWidth = parseFloat(bar.getAttribute('data-max-width'));
    var fixedInset = parseFloat(getComputedStyle(bar).paddingLeft);
    var name = bar.textContent.replace(/\s+/g, ' ').trim();

    function measure(lines) {
      bar.textContent = lines.join('\n');
      return { lines: lines, width: bar.offsetWidth };
    }

    function narrowest(layouts) {
      return layouts.reduce(function (best, current) {
        return best === null || current.width < best.width ? current : best;
      }, null);
    }

    var spaceSplits = [];
    var hyphenSplits = [];
    for (var i = 1; i < name.length; i++) {
      if (name.charAt(i) === ' ') {
        spaceSplits.push(measure([name.slice(0, i), name.slice(i + 1)]));
      } else if (name.charAt(i - 1) === '-') {
        hyphenSplits.push(measure([name.slice(0, i), name.slice(i)]));
      }
    }

    // how much a layout may be scaled down to avoid a worse line break
    var slightlyTooWide = maxWidth * 1.06;
    var noticeablyTooWide = maxWidth * 1.12;

    var best = measure([name]);
    if (best.width > slightlyTooWide) {
      var bySpace = narrowest(spaceSplits);
      var byHyphen = narrowest(hyphenSplits);
      if (bySpace !== null && bySpace.width <= noticeablyTooWide) {
        best = bySpace;
      } else if (byHyphen !== null && byHyphen.width <= maxWidth) {
        best = byHyphen;
      } else {
        best = narrowest([best, bySpace, byHyphen].filter(function (layout) { return layout !== null; }));
      }
    }

    bar.textContent = best.lines.join('\n');
    if (best.width > maxWidth) {
      var fontSize = parseFloat(getComputedStyle(bar).fontSize);
      bar.style.fontSize = (fontSize * (maxWidth - fixedInset) / (best.width - fixedInset)) + 'px';
    }
  }

  // Measure only with the SRG SSR Type font loaded, the fallback font has different widths
  var weights = ['400', '500', '700'];
  Promise.all(weights.map(function (weight) {
    return document.fonts.load(weight + ' 20px "SRG SSR Type"');
  })).then(layout, layout);
})();
